extra_sources.internal/checker/selected_consumer_contr:
package checker

import "github.com/microsoft/typescript-go/internal/ast"

type SelectedConsumerControl struct {
 AliasOriginal, AliasImmediate, CopiesDistinct, PrototypeSymbolShared, PrototypeParentShared, PrototypeTypeShared, WarmStable, TailShared, TailError bool
 TargetName string
}

func (c *Checker) QualifySelectedConsumers(head, twin, raw, react, original, tail *ast.Symbol, reverse bool) SelectedConsumerControl {
 if reverse { c.getTypeOfSymbol(tail) }
 h := c.getTypeOfSymbol(head)
 t := c.getTypeOfSymbol(twin)
 r := c.getTypeOfSymbol(raw)
 hp := c.getPropertyOfType(h, "prototype")
 tp := c.getPropertyOfType(t, "prototype")
 rp := c.getPropertyOfType(r, "prototype")
 target := c.resolveAlias(react)
 module := c.resolveExternalModuleName(c.getDeclarationOfAliasSymbol(react), c.getModuleSpecifierForImportOrExport(c.getDeclarationOfAliasSymbol(react)), true)
 immediate := c.getTargetOfModuleDefault(module, c.getDeclarationOfAliasSymbol(react), true)
 row := SelectedConsumerControl{AliasOriginal: target == original, AliasImmediate: target == immediate, TargetName: target.Name, CopiesDistinct: h != r && h != t && t != r, PrototypeSymbolShared: hp == rp && tp == rp, PrototypeParentShared: c.getParentOfSymbol(hp) == c.getParentOfSymbol(rp), PrototypeTypeShared: c.getTypeOfSymbol(hp) == c.getTypeOfSymbol(rp) && c.getTypeOfSymbol(tp) == c.getTypeOfSymbol(rp), WarmStable: true, TailShared: c.getTypeOfSymbol(tail) == h, TailError: c.getTypeOfSymbol(tail) == c.errorType}
 for i:=0;i<3;i++ { row.WarmStable = row.WarmStable && c.resolveAlias(react) == target && c.getTypeOfPropertyOfType(h,"prototype") == c.getTypeOfPropertyOfType(r,"prototype") }
 return row
}

package checker_test

import (
 "encoding/json"
 "testing"
 "github.com/microsoft/typescript-go/internal/ast"
 "github.com/microsoft/typescript-go/internal/bundled"
 "github.com/microsoft/typescript-go/internal/compiler"
 "github.com/microsoft/typescript-go/internal/core"
 "github.com/microsoft/typescript-go/internal/tsoptions"
 "github.com/microsoft/typescript-go/internal/vfs/vfstest"
)

func TestTSRSelectedConsumers(t *testing.T) {
 for _,generic := range []bool{false,true} { for _,reverse := range []bool{false,true} { for _,namespace:=range []bool{false,true} {
 lib := "class Foo {field:number;static item=1;} export=Foo;"
 if generic {lib="class Foo<T> {field:T;static item=1;} export=Foo;"}
 if namespace {lib+=" namespace Foo {export const token=1;}"}
 fs:=bundled.WrapFS(vfstest.FromMap(map[string]string{
 "/lib.ts":lib,
 "/use.ts":"import * as Head from './lib'; import * as Twin from './lib'; import Raw = require('./lib'); import React from 'pure'; import Tail = Linked; import Linked = Head;",
 "/ambient.d.ts":"declare module 'pure' { namespace Original { interface Pair<A,B> {left:A;right:B;} } export=Original; }",
 "/tsconfig.json":`{"compilerOptions":{"module":"commonjs","esModuleInterop":true,"strict":true,"noEmit":true},"files":["lib.ts","use.ts","ambient.d.ts"]}`,
 },false))
 host:=compiler.NewCompilerHost("/",fs,bundled.LibPath(),nil,nil)
 parsed,errors:=tsoptions.GetParsedCommandLineOfConfigFile("/tsconfig.json",&core.CompilerOptions{},nil,host,nil)
 if len(errors)!=0 {t.Fatal(errors)}
 p:=compiler.NewProgram(compiler.ProgramOptions{Config:parsed,Host:host});p.BindSourceFiles();c,done:=p.GetTypeChecker(t.Context())
 syms:=map[string]*ast.Symbol{}
 var visit func(*ast.Node)bool
 visit=func(n *ast.Node)bool {if n.Kind==ast.KindIdentifier { name:=n.Text();switch name {case "Head","Twin","Raw","React","Original","Tail":if _,present:=syms[name]; !present {syms[name]=c.GetSymbolAtLocation(n)}}};n.ForEachChild(visit);return false}
 p.GetSourceFile("/use.ts").ForEachChild(visit);p.GetSourceFile("/ambient.d.ts").ForEachChild(visit)
 for _,name:=range []string{"Head","Twin","Raw","React","Original","Tail"} {if syms[name]==nil {t.Fatal(name)}}
 row:=c.QualifySelectedConsumers(syms["Head"],syms["Twin"],syms["Raw"],syms["React"],syms["Original"],syms["Tail"],reverse)
 data,_:=json.Marshal(row);t.Logf("generic=%v reverse=%v namespace=%v %s",generic,reverse,namespace,data)
 if !row.AliasOriginal || row.AliasImmediate || !row.CopiesDistinct || !row.PrototypeSymbolShared || !row.PrototypeParentShared || !row.PrototypeTypeShared || !row.WarmStable || row.TailShared != namespace || row.TailError == namespace {t.Error("native consumer contract",row)}
 done()
 }}}
}

